using System;
using System.Collections;
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using Chaos.ArrayExtensions;
using UnityEngine;

[AddComponentMenu("Chaos/Enemies/Enemy")]
public class Enemy : Entity
{
	public delegate void AddEnemyEventHandler(GameObject newEnemyObj);

	public delegate void EnemySpawnEventHandler(Enemy newEnemy);

	public enum EName
	{
		Blob,
		BlobMini,
		BlobSpitter,
		BlobRoller,
		Ghoul,
		GhoulLarge,
		Coffin,
		MovingStatue,
		EnemyTurret,
		PoisonPlant,
		MimicEnemy,
		MimicEnemyLarge,
		OrbChargeFamiliar,
		OrbRevolveFamiliar,
		OrbShootFamiliar,
		Archer,
		Knight,
		SkeletonMage,
		Rogue,
		Lancer,
		Summoner,
		FrostArcher,
		FrostKnight,
		FrostMage,
		FrostRogue,
		FrostLancer,
		FrostSummoner,
		EarthArcher,
		EarthKnight,
		EarthMage,
		EarthRogue,
		EarthLancer,
		EarthSummoner,
		FlameArcher,
		FlameKnight,
		FlameMage,
		FlameRogue,
		FlameLancer,
		FlameSummoner,
		WindArcher,
		WindKnight,
		WindMage,
		WindRogue,
		WindLancer,
		WindSummoner,
		ThunderArcher,
		ThunderKnight,
		ThunderMage,
		ThunderRogue,
		ThunderLancer,
		ThunderSummoner,
		FrostZoneEnemy,
		EarthZoneEnemy,
		FlameZoneEnemy,
		WindZoneEnemy,
		ThunderZoneEnemy,
		Cyclops,
		LaserOrb,
		Spider,
		SpikeSpider,
		Dove,
		Rat,
		Eagle,
		SuperKnight,
		SuperMage,
		SuperRogue,
		SuperArcher,
		SuperLancer,
		SuperSummoner,
		SuperCoffin,
		SuperBlob,
		SuperMovingStatue,
		Contestant
	}

	[Serializable]
	public class SkillState : State<Enemy>
	{
		public string skillID;

		public int requiredDifficultyLevel;

		public int priorityLevel;

		public float minActivationRadius;

		public float maxActivationRadius;

		public float cooldownTime;

		public Cooldown cooldownRef;

		private static SyncedNumVarStat windupMultiStat;

		private static SyncedNumVarStat exitMultiStat;

		private static SyncedNumVarStat cooldownMultiStat;

		public string castingAnimName = string.Empty;

		public PowerUpEffect powerUpEffect;

		public Transform powerUpTrans;

		public bool usePowerUpEffect = true;

		public bool playPowerUpAudio = true;

		public bool disablePowerUpEffect;

		public Color spellCastColor = defaultCastColor;

		public Vector2 targetVector;

		public bool useTargetHurtBox = true;

		public bool requireLineOfSight = true;

		public bool isLegendary;

		public float currentDiffValue;

		public int windupStopwatchID = -1;

		public float windupTime = -1f;

		public bool windupComplete;

		public float exitTime = -1f;

		public int exitStopwatchID = -1;

		public bool exitQueued;

		private bool registered;

		public bool isChargeSkill;

		public static SyncedNumVarStat WindupMultiStat
		{
			get
			{
				if (windupMultiStat == null)
				{
					windupMultiStat = new SyncedNumVarStat(1f);
				}
				return windupMultiStat;
			}
		}

		public static SyncedNumVarStat ExitMultiStat
		{
			get
			{
				if (exitMultiStat == null)
				{
					exitMultiStat = new SyncedNumVarStat(1f);
				}
				return exitMultiStat;
			}
		}

		public static SyncedNumVarStat CooldownMultiStat
		{
			get
			{
				if (cooldownMultiStat == null)
				{
					cooldownMultiStat = new SyncedNumVarStat(1f);
				}
				return cooldownMultiStat;
			}
		}

		public virtual float StdWindupTime => Mathf.Lerp(0.5f, 0.35f, currentDiffValue) * WindupMultiStat.CurrentValue;

		public virtual float StdExitTime => Mathf.Lerp(0.75f, 0.5f, currentDiffValue) * ExitMultiStat.CurrentValue;

		public virtual bool WindupCheck => windupComplete;

		public SkillState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt)
		{
			skillID = newName;
			requiredDifficultyLevel = newReq;
			priorityLevel = newPriority;
			minActivationRadius = newMin;
			maxActivationRadius = newMax;
			cooldownTime = Mathf.Max(2f, newCD * CooldownMultiStat.CurrentValue);
			RegisterSkill(newAuto);
		}

		public static void ApplyGlobalMods(NumVarStatMod givenCD = null, NumVarStatMod givenWindup = null, NumVarStatMod givenExit = null, bool givenStatus = true)
		{
			if (givenCD != null)
			{
				CooldownMultiStat.Modify(givenCD, givenStatus);
			}
			if (givenWindup != null)
			{
				WindupMultiStat.Modify(givenWindup, givenStatus);
			}
			if (ExitMultiStat != null)
			{
				ExitMultiStat.Modify(givenExit, givenStatus);
			}
		}

		public void RegisterSkill(bool makeAvailableToAI = true, bool addToCooldowns = true)
		{
			if (makeAvailableToAI)
			{
				parent.availableEnemySkillsDict[skillID] = this;
			}
			else
			{
				parent.availableEnemySkillsDict.Remove(skillID);
			}
			if (addToCooldowns)
			{
				parent.cooldownManager.Add(skillID, cooldownTime);
				cooldownRef = parent.cooldownManager.cooldowns[skillID];
			}
			registered = true;
		}

		public void InitChargeSkillSettings(int maxCharges, float cooldownTime)
		{
			isChargeSkill = true;
			cooldownRef.isChargeSkill = true;
			cooldownRef.chargeCount = maxCharges;
			cooldownRef.MaxChargeCount = maxCharges;
			cooldownRef.remainingTimeStopwatchID = -1;
			cooldownRef.MaxTime = cooldownTime;
		}

		public bool BaseSkillIsReady()
		{
			if (parent.CurrentDifficulty < requiredDifficultyLevel)
			{
				return false;
			}
			if (isChargeSkill)
			{
				return parent.cooldownManager.cooldowns[skillID].chargeCount > 0;
			}
			return parent.cooldownManager.CheckCooldown(skillID);
		}

		public virtual bool IsReady()
		{
			return BaseSkillIsReady();
		}

		public bool Transition(bool checkIsReady = true)
		{
			if (fsm.currentStateName.Contains(skillID) || (checkIsReady && !IsReady()))
			{
				return false;
			}
			fsm.ChangeState(skillID, allowSelfTransition: true);
			return true;
		}

		public virtual void ExitTransition()
		{
			parent.HandleExitTransitions();
		}

		public void StartCooldown(float overrideValue = -1f)
		{
			if (!registered || (cooldownTime <= 0f && overrideValue <= 0f) || parent == null)
			{
				return;
			}
			if (isChargeSkill)
			{
				if (cooldownRef.chargeCount > 0)
				{
					cooldownRef.chargeCount--;
				}
				parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
			}
			else
			{
				parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
			}
		}

		public override void OnEnter()
		{
			parent.enemySkillUseInProgress = true;
			StartCooldown();
			currentDiffValue = parent.DifficultyValue;
			isLegendary = parent.IsLegendary;
			UpdateTargetVector();
			if (parent.closestTargetInfo != null)
			{
				parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			}
			if (usePowerUpEffect)
			{
				ActivatePowerUpEffect(spellCastColor);
			}
			windupComplete = false;
			exitQueued = false;
		}

		public override void Update()
		{
			if (!WindupCheck)
			{
				if (ChaosStopwatch.Check(windupStopwatchID))
				{

			{
				ExecuteSkill();
			}
			else
			{
				WindupUpdate();
			}
		}
		else if (exitQueued && ChaosStopwatch.Check(exitStopwatchID))
		{
			ExitTransition();
		}
	}

	public override void OnExit()
	{
		parent.enemySkillUseInProgress = false;
		if (usePowerUpEffect)
		{
			DeactivatePowerUpEffect();
		}
	}

	public virtual void ActivatePowerUpEffect(Color color, Color? color2 = null, bool skipOutline = false)
	{
		if (!disablePowerUpEffect)
		{
			powerUpEffect = PoolManager.GetPoolItem<PowerUpEffect>();
			if (parent.spriteRenderer != null)
			{
				powerUpEffect.Activate(parent.spriteRenderer.transform, color);
			}
			else
			{
				powerUpEffect.Activate(powerUpTrans ?? parent.transform, color);
			}
			if (!skipOutline)
			{
				parent.SetOutlineColor(color, color2);
			}
			if (playPowerUpAudio)
			{
				SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			}
		}
	}

	public virtual void DeactivatePowerUpEffect(bool skipBreakEffect = false)
	{
		if (powerUpEffect != null)
		{
			powerUpEffect.Deactivate();
		}
		if (!disablePowerUpEffect)
		{
			if (!skipBreakEffect && parent.spriteRenderer.material.GetColor("_OutlineColor") == armorCastColor && !parent.currentStateName.Contains("Dead"))
			{
				PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, parent.transform.position);
			}
			parent.SetOutlineColor(Color.clear, Color.clear);
		}
	}

	public virtual Vector2 UpdateTargetVector(bool updateInfo = false, bool useTransform = false)
	{
		if (updateInfo)
		{
			parent.UpdateTargetInfo();
		}
		if (parent.closestTargetInfo == null || (useTransform && (parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)))
		{
			targetVector = Vector2.zero;
		}
		else
		{
			ref Vector2 reference = ref targetVector;
			Vector3 vector;
			if (useTargetHurtBox)
			{
				vector = ((!useTransform) ? parent.closestTargetInfo.hurtBoxPosition : parent.closestTargetInfo.hurtBoxTransform.position);
			}
			else
			{
				vector = ((!useTransform) ? parent.closestTargetInfo.position : parent.closestTargetInfo.transform.position);
			}
			reference = vector;
			targetVector = ((!useTargetHurtBox) ? (targetVector - (Vector2)parent.transform.position) : (targetVector - (Vector2)parent.hurtBoxTransform.position)).normalized;
		}
		return targetVector;
	}

	public virtual void WindupUpdate()
	{
	}

	public virtual void ExecuteSkill()
	{
		windupComplete = true;
		exitStopwatchID = ChaosStopwatch.Begin((!(exitTime >= 0f)) ? StdExitTime : exitTime);
		exitQueued = true;
	}

	public virtual T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
	{
		return Globals.ChaosInst<T>(givenPrefab, parentTransform ?? parent.transform.parent, (!givenPosition.HasValue) ? ((Vector2)parent.transform.position) : givenPosition.Value, (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value);
	}
}

public class DashState : SkillState
{
	public bool dashRandom;

	public bool dashAway;

	public float dashSpeed;

	public float dashDuration;

	public float dashRange;

	public bool dashOverPits;

	public bool onlyDashOverPits;

	public float randomOffSet;

	public bool disableFloorContact;

	public bool playDashEffects;

	public bool isDashing;

	public Vector2 dashVector;

	public Vector2 destinationPosition;

	public bool destinationIsSafe;

	public float distanceTodestination;

	public bool allowReset;

	public bool trackTarget = true;

	public bool getRandomNearby = true;

	public NumVarStatMod dashSpeedMod;

	public NumVarStatMod dashDurationMod;

	public BoolVarStatMod airborneStatMod;

	public DashState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
		: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
	{
		if (newReq <= parent.CurrentDifficulty)
		{
			parent.lineOfSightLayerMask = ChaosCollisions.layerAllWallAndObst;
		}
		playPowerUpAudio = false;
		dashOverPits = false;
		onlyDashOverPits = false;
		dashRandom = false;
		dashAway = false;
		dashSpeed = 30f;
		dashRange = 6f;
		randomOffSet = 0f;
		disableFloorContact = true;
		playDashEffects = true;
		dashSpeedMod = new NumVarStatMod("dashOverride", dashSpeed, 10, VarStatModType.OverrideWithMods);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 5);
	}

	public override bool IsReady()
	{
		if (!base.IsReady())
		{
			return false;
		}
		if (!parent.CanMove || parent.closestTargetInfo == null)
		{
			StartCooldown(1f);
			return false;
		}
		dashVector = GetDashVector(parent.closestTargetInfo.position);
		destinationPosition = GetDestinationVector(parent.transform.position, parent.closestTargetInfo.position);
		destinationIsSafe = destinationPosition != Vector2.zero && Globals.CheckCircle(destinationPosition, 0.25f, ChaosCollisions.layerPit);
		if (!destinationIsSafe)
		{
			StartCooldown(1f);
			return false;
		}
		if (dashOverPits && allowReset && !Entity.HasLineOfSight(parent.transform.position, parent.closestTargetInfo.position, 1.5f, ChaosCollisions.layerPit, adjustToRange: true))
		{
			return true;
		}
		if (onlyDashOverPits)
		{
			StartCooldown(0.5f);
			return false;
		}
		return true;
	}

	public virtual Vector2 GetRandomVector()
	{
		return UnityEngine.Random.insideUnitCircle * randomOffSet;
	}

	public virtual Vector2 GetDashVector(Vector2 givenTargetLoc)
	{
		if (dashRandom)
		{
			dashAway = Globals.RandBool;
		}
		return ((givenTargetLoc - (Vector2)parent.transform.position) * ((!dashAway) ? 1 : (-1)) + GetRandomVector()).normalized;
	}

	public virtual Vector2 GetDestinationVector(Vector2 givenPosition, Vector2 givenTargetLoc)
	{
		return Globals.GetLinecastVector(givenPosition, (dashAway || !trackTarget || !(Vector2.Distance(givenPosition, givenTargetLoc) < dashRange)) ? (givenPosition + dashVector * dashRange) : givenTargetLoc, ChaosCollisions.layerAllWallAndObst) - dashVector * 0.25f;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.anim.Play(castingAnimName, -1, 0f);
		dashVector = (destinationPosition - (Vector2)parent.transform.position).normalized;
		distanceTodestination = Vector2.Distance(parent.transform.position, destinationPosition);
		dashDuration = distanceTodestination / dashSpeed;
		allowReset = dashOverPits;
		parent.movement.dashVector = dashVector;
		dashSpeedMod.modValue = dashSpeed;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		parent.airborneStat.AddMod(airborneStatMod);
		if (playDashEffects)
		{
			PlayDashEffects();
		}
