public class RoamState : State<Enemy>
{
	public int maxRetries = 3;

	public float roamDistance = 6f;

	public int losLayerMask;

	public string animName = "Run";

	public bool updateFacingDirection = true;

	public Vector2 newPosition;

	public bool isRoaming;

	public float maxTime = 2f;

	public int maxStopwatchID;

	public float approachRadius = 0.5f;

	public float castRadius = 0.125f;

	public RoamState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		losLayerMask = ChaosCollisions.layerAll;
	}

	public override void OnEnter()
	{
		isRoaming = false;
		for (int i = 0; i < maxRetries; i++)
		{
			newPosition = GetNewPosition();
			if ((i + 1 >= maxRetries || !(Vector2.Distance(parent.transform.position, newPosition) < 0.5f * roamDistance)) && parent.CanApproachTarget(parent.transform.position, newPosition, 30f, losLayerMask, parent.traversableNodeMap))
			{
				isRoaming = true;
				maxStopwatchID = ChaosStopwatch.Begin(maxTime);
				parent.anim.PlayDirectional(animName + ((!updateFacingDirection) ? string.Empty : parent.facingDirection.ToString()));
				break;
			}
		}
	}

	public override void Update()
	{
		if (!isRoaming || ChaosStopwatch.Check(maxStopwatchID))
		{
			ExitTransition();
		}
		else
		{
			isRoaming = !parent.MoveToTargetOrFollowPath(chasingTarget: false, parent.transform.position, newPosition, roamDistance, approachRadius, animName, updateFacingDirection);
		}
	}

	public virtual Vector2 GetNewPosition()
	{
		return Globals.GetCirclecastVector(parent.transform.position, castRadius, UnityEngine.Random.insideUnitCircle.normalized, roamDistance, losLayerMask);
	}

	public virtual void ExitTransition()
	{
		fsm.ChangeState(fsm.defaultStateName);
	}
}

