			return;
		}
		currentPosition = parent.transform.position;
		moveVec = ((Vector2)parent.closestTargetInfo.position - currentPosition).normalized;
		perpendVec = Globals.GetPerpendicular(moveVec);
		moveVec *= 0.75f;
		base.OnEnter();
	}

	public override Vector2 GetNewPosition()
	{
		return Globals.GetCirclecastVector(currentPosition, castRadius, (moveVec + Vector2.Lerp(-perpendVec, perpendVec, UnityEngine.Random.value)).normalized, roamDistance, losLayerMask);
	}

	public override void OnExit()
	{
		if (parent.closestTargetInfo != null)
		{
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
		}
	}
