public class SurroundState : State<Enemy>
{
	public SurroundState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
	}

	public override void OnEnter()
	{
		parent.currentSurroundPoint = parent.GetSurroundPoint();
		parent.anim.PlayDirectional("Run" + ((parent.animFacingDirections != 2) ? parent.facingDirection.ToString() : "Right"));
	}

	public override void Update()
	{
		parent.UpdateTargetInfo(parent.escapeRadius);
		if (parent.closestTargetInfo == null)
		{
			fsm.ChangeState((!fsm.HasState("GoBack")) ? fsm.defaultStateName : "GoBack");
			return;
		}
		if (!Entity.HasLineOfSight(parent.transform.position, parent.closestTargetInfo.position, parent.CurrentAlertRadius, parent.lineOfSightLayerMask))
		{
			fsm.ChangeState("Chase");
			return;
		}
		parent.PlayAnimOnFaceDirChange("Run", parent.closestTargetInfo.position, parent.animFacingDirections);
		parent.currentSurroundPoint = parent.GetSurroundPoint();
		float distance = parent.closestTargetInfo.distance;
		if (parent.HandleExtraSkills(hasLOS: true, updateTarget: false, updateLOS: true))
		{
			return;
		}
		if (distance <= parent.attackRadius)
		{
			fsm.ChangeState("Attack");
			return;
		}
		Vector2 vector = (Vector2)parent.closestTargetInfo.position + parent.currentSurroundPoint.normalized * parent.attackRadius;
		if (parent.currentSurroundPoint != Vector2.zero && parent.movement.MoveToTarget(vector))
		{
			fsm.ChangeState("Attack");
		}
		else if (Vector2.Distance(vector, parent.transform.position) > parent.surroundRadius)
		{
			fsm.ChangeState("Chase");
		}
	}

	public override void OnExit()
	{
		if (!fsm.nextState.name.Contains("Attack"))
		{
			parent.ReleaseSurroundPoint();
		}
	}
}

