public class EnemyDeadState : DeadState
{
	public Vector3 lootSpawnLocation;

	public bool isDead;

	public bool playDeadEffectAudio = true;

	private int deadAudioCount = -1;

	private AttackInfo lastAtk;

	public new Enemy parent;

	public EnemyDeadState(string newName, FSM newFSM, Enemy newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		isDead = false;
		lootSpawnLocation = Vector3.zero;
		if (parent.deadAudioIDs != null)
		{
			deadAudioCount = parent.deadAudioIDs.Length;
		}
	}

	public override void OnEnter()
	{
		if (isDead)
		{
			return;
		}
		base.OnEnter();
		if (parent.canAlertOthers)
		{
			parent.AlertNearbyEnemies();
		}
		EnemyDropLoot();
		if (playDeadEffectAudio)
		{
			PlayDeadAudio();
		}
		parent.ReleaseSurroundPoint();
		parent.currentGroup.Remove(parent.gameObject);
		GameDataManager.gameData.gameStats.EnemyDefeated(parent.enemyTypeString);
		isDead = true;
		Level.enemiesDefeatedCount++;
		lastAtk = parent.health.lastAttack;
		if (lastAtk != null && lastAtk.entity is Player)
		{
			if (parent.countDeathInStats)
			{
				(lastAtk.entity as Player).OnEnemyKill(parent);
			}
			(lastAtk.entity as Player).OnEnemyKillAbs(parent, lastAtk);
		}
	}

	public override void Update()
	{
		base.Update();
		if (animPlayed)
		{
			if (parent.destroyOnDeath)
			{
				UnityEngine.Object.Destroy(parent.gameObject);
			}
			else
			{
				parent.GetComponent<Enemy>().enabled = false;
			}
		}
	}

	public virtual void EnemyDropLoot()
	{
		if (lootSpawnLocation == Vector3.zero)
		{
			lootSpawnLocation = parent.transform.position;
		}
		if (!parent.dropLoot)
		{
			return;
		}
		if (parent.dropLootChest)
		{
			TreasureChest component = UnityEngine.Object.Instantiate(TreasureChest.Prefab, lootSpawnLocation, Quaternion.identity).GetComponent<TreasureChest>();
			if (parent.chestLootTableID != string.Empty)
			{
				component.lootTableName = parent.chestLootTableID;
			}
		}
		else
		{
			LootManager.DropLoot(parent.enemyTypeString, lootSpawnLocation);
		}
	}

	public virtual void PlayDeadAudio()
	{
		SoundManager.PlayAudioWithDistance("EnemyDead", parent.transform.position);
		if (deadAudioCount >= 0)
		{
			string audioID = parent.deadAudioIDs[UnityEngine.Random.Range(0, deadAudioCount)];
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = UnityEngine.Random.Range(parent.minPitch, parent.maxPitch);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
	}
}

