public int SetPaletteIndex(SpriteRenderer sRenderer)
{
	int result = 0;
	if (sRenderer == null || !elementToPalette.ContainsKey(element) || sRenderer.material == null || !sRenderer.material.HasProperty("_PaletteCount"))
	{
		return result;
	}
	int num = (int)sRenderer.material.GetFloat("_PaletteCount");
	result = ((element != ElementType.Neutral || num <= EnemyElementCount + 1 || GameController.CurrentDifficulty <= 0) ? elementToPalette[element] : Mathf.Clamp(GameController.CurrentDifficulty, 0, 2));
	sRenderer.material.SetFloat("_PaletteIndex", result);
	paletteIndex = result;
	return result;
}

