		{
			doubleAttack = queueDoubleAttack;
			queueDoubleAttack = parent.IsStealthed || (alwaysDouble && !doubleAttack);
			parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID, (!queueDoubleAttack) ? 1 : 2);
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			parent.anim.Play("Attack", -1, (!queueDoubleAttack) ? 0.25f : 0.4f);
			if (parent.closestTargetInfo.hurtBoxTransform != null)
			{
				parent.attack.transform.localEulerAngles = Globals.GetRotationVector((parent.closestTargetInfo.hurtBoxTransform.position - parent.hurtBoxTransform.position).normalized) * ((!parent.isFacingRight) ? (-1f) : 1f);
			}
			parent.movement.EndMovement();
			soundPlayed = false;
			calcExitTime = 1.25f;
		}

		public override void Update()
		{
			if (parent.attackAudioID != string.Empty && !soundPlayed && parent.anim.AnimPlayed(parent.attackAnimAudioPlayTime))
			{
				soundPlayed = true;
				string attackAudioID = parent.attackAudioID;
				Vector2? soundOrigin = parent.transform.position;
				float overridePitch = UnityEngine.Random.Range(parent.minPitch, parent.maxPitch);
				SoundManager.PlayAudioWithDistance(attackAudioID, soundOrigin, null, 24f, -1f, overridePitch);
			}
			if (queueDoubleAttack && parent.anim.AnimPlayed(0.6f))
			{
				fsm.ChangeState("Attack", allowSelfTransition: true);
			}
			else if (parent.anim.AnimPlayed(calcExitTime))
			{
				ExitTransition();
			}
		}

