	public class LancerLeapAttackState : SkillState
	{
		protected Vector2 jumpLocation;

		protected float jumpOffset = -0.25f;

		protected bool hasJumped;

		protected bool hasLanded;

		protected bool attackCreated;

		protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch(0.5f);

		protected BoolVarStatMod airborneStatMod;

		protected CastingCircle castingCircle;

		protected bool useCastingCircle = true;

		protected float lanceAtkRadius = 2f;

		protected LanceStrike currentLS;

		protected bool emitFloorCrater = true;

		protected bool useAltJumpAnim = true;

		public new Lancer parent;

		public LancerLeapAttackState(string newName, FSM newFSM, Lancer newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			useTargetHurtBox = false;
			airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
		}

		public override bool IsReady()
		{
			return parent.MovementEnabled && base.IsReady();
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("JumpWindup", -1, 0f);
			jumpLocation = ((parent.closestTargetInfo != null) ? parent.closestTargetInfo.position : parent.transform.position);
			ThrownItem throwScript = parent.throwScript;
			throwScript.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(throwScript.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			if (useCastingCircle)
			{
				castingCircle = CastingCirclePool.Spawn("Spin", parent.transform.position, parentObj: parent.gameObject, color: CastingCircle.enemyColor, disableWithParentVal: true, trackParentVal: true, useCastTimeVal: false, castTimeVal: 0f, unitSizeX: lanceAtkRadius);
			}
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.25f);
			hasJumped = false;
			hasLanded = false;
			attackCreated = false;
		}

		public override void Update()
		{
			if (!hasJumped)
			{
				if (ChaosStopwatch.Check(windupStopwatchID))
				{
					hasJumped = true;
					if (useAltJumpAnim)
					{
						parent.anim.Play("JumpAlt", -1, 0f);
					}
					else
					{
						parent.anim.Play("Jump", -1, 0f);
					}
					parent.spriteRenderer.sortingLayerName = "UI";
					parent.throwScript.ThrowToTargetVector(jumpLocation + targetVector * jumpOffset);
					DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
					int particleCount = 50;
					float scale = 0.25f;
					Vector3? emitPosition = parent.transform.position;
					poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
					string audioID = "StandardJump";
					Vector2? soundOrigin = parent.transform.position;
					scale = SoundManager.StandardPitchRange;
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
					ToggleObjects(status: false);
				}
			}
			else
			{
				if (!attackCreated && parent.throwScript.isFalling)
				{
					attackCreated = true;
					CreateLanceStrike();
				}
				if (hasLanded && !landingStopwatch.IsRunning)
				{
					ExitTransition();
				}
			}
		}

		public override void OnExit()
		{
			if (hasJumped && !hasLanded)
			{
				OnLanding();
			}
			base.OnExit();
			ToggleObjects(status: true);
			ThrownItem throwScript = parent.throwScript;
			throwScript.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(throwScript.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			if (castingCircle != null)
			{
				castingCircle.Reset();
			}
		}

		public virtual void OnLanding()
		{
			hasLanded = true;
			ToggleObjects(status: true);
			landingStopwatch.IsRunning = true;
			parent.spriteRenderer.sortingLayerName = "Actor";
			DeactivatePowerUpEffect();
			jumpLocation = parent.transform.position;
			if (emitFloorCrater)
			{
				PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, jumpLocation);
			}
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 100;
			float scale = 0.25f;
			Vector3? emitPosition = jumpLocation;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			string audioID = "GroundSlam";
			Vector2? soundOrigin = jumpLocation;
			scale = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
		}

		public virtual void ToggleObjects(bool status)
		{
			parent.airborneStat.Modify(airborneStatMod, !status);
			parent.hurtBoxTransform.gameObject.SetActive(status);
			parent.floorContact.SetActive(status);
			parent.TogglePreventFallCollider(status);
		}

		public virtual void CreateLanceStrike()
		{
			currentLS = ChaosInst<LanceStrike>(LanceStrike.Prefab, (Vector2)parent.transform.position + targetVector);
			currentLS.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentLS.attackRadius = lanceAtkRadius;
			currentLS.SetPaletteIndex(parent.paletteIndex);
			if (castingCircle != null)
			{
				castingCircle.Reset();
			}
		}
	}

