using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class MiniBoss : Enemy
{
	public delegate void MiniBossSpawnEvent(MiniBoss miniBoss);

	public delegate void MiniBossComboEvent(MiniBoss miniBoss, int comboCount);

	public class MiniBossReadyState(string newName, FSM newFSM, MiniBoss newEnt) : State<MiniBoss>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;

		public int readyStopwatchID;

		public override void OnEnter()
		{
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
			readyStopwatchID = ChaosStopwatch.Begin(Mathf.Lerp(0.75f, 0.5f, parent.DifficultyValue) * SkillState.WindupMultiStat.CurrentValue);
			parent.AllowHurtState(status: false);
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(readyStopwatchID))
			{
				parent.HandleExitTransitions();
			}
		}
	}

	public class MiniBossHurtState : EnemyHurtState
	{
		public string animName = "Hurt";

		public float baseHurtDuration;

		public float maxHurtDuration;

		public float durationIncreaseMultiplier = 0.75f;

		public int hurtStopwatchID;

		public float stunOverrideValue = 2f;

		public AttackInfo lastAttackInfo;

		public NumVarStatMod kbMod;

		public float hitToDmgRatio = 0.02f;

		public int minComboCount = 5;

		public int hitCounter;

		private bool varsSet;

		public new MiniBoss parent;

		public MiniBossHurtState(string newName, FSM newFSM, MiniBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			kbMod = new NumVarStatMod("BossKnockback", 0.25f, 10, VarStatModType.Override);
			Reset();
		}

		public virtual void SetHurtVars()
		{
			baseHurtDuration = Mathf.Lerp(1f, 0.625f, parent.DifficultyValue) * Boss.BaseHurtDurationMultiplier.CurrentValue;
			maxHurtDuration = baseHurtDuration * 2f;
			parent.health.knockbackModifierStat.AddMod(kbMod);
		}

		public override void OnEnter()
		{
			if (!varsSet)
			{
				varsSet = true;
				SetHurtVars();
			}
			if (animName != string.Empty)
			{
				parent.anim.Play(animName, -1, 0f);
			}
			PlayHurtAudio();
			lastAttackInfo = parent.health.lastAttack;
			HandleDurationIncrease(fsm.previousStateName != name);
			HandleStunEffect();
			if (parent.health != null)
			{
				parent.ApplyKnockback(lastAttackInfo);
			}
			if (!Level.isBossRushMode && hitCounter >= minComboCount)
			{
				GameUI.BroadcastNoticeMessage(hitCounter + TextManager.GetUIText("bossRoom-comboCounter"));
			}
		}

		public override void Update()
		{
			exitHurtState = ChaosStopwatch.Check(hurtStopwatchID);
			if (!exitHurtState)
			{
				return;
			}
			if (hitCounter >= minComboCount)
			{
				GameController.stageTitleUI.AnnounceCombo(hitCounter);
				if (hitCounter >= 50)
				{
					AchievementManager.UnlockAchievement(Achievement.HitSpellCombo, forceUnlock: true);
				}
				if (miniBossComboEventHandlers != null)
				{
					miniBossComboEventHandlers(parent, hitCounter);
				}
			}
			ExitTransition();
		}

		public override void OnExit()
		{
			if (!parent.fsm.nextStateName.Contains("Hurt"))
			{
				Reset();
			}
		}

		public override void ExitTransition()
		{
			if (fsm.HasState("Ready"))
			{
				fsm.ChangeState("Ready");
			}
			else
			{
				parent.HandleExitTransitions();
			}
		}

		public virtual void Reset()
		{
			hitCounter = 0;
			parent.AllowHurtState(status: false);
			if (stunEffect != null)
			{
				stunEffect.Stop(!parent.fsm.nextStateName.Contains("Dead") && !parent.fsm.nextStateName.Contains("Fall"));
				stunEffect = null;
			}
		}

		public virtual void HandleDurationIncrease(bool first = false)
		{
			if (first)
			{
				hitCounter = 1;
				hurtStopwatchID = ChaosStopwatch.Begin(baseHurtDuration);
				return;
			}
			if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
			{
				hitCounter++;
			}
			hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
		}

		public virtual void HandleStunEffect()
		{
			if (base.stunEffect == null)
			{
				base.stunEffect = PoolManager.GetPoolItem<StunEffect>();
				base.stunEffect.fullStunOverride = stunOverrideValue;
				base.stunEffect.Play(hurtStopwatchID, parent.transform, Vector3.up * 3.25f);
			}
			else
			{
				StunEffect stunEffect = base.stunEffect;
				int givenStopwatchID = hurtStopwatchID;
				stunEffect.Readjust(-1f, givenStopwatchID);
			}
		}
	}

