	public class BossReadyState : BossSkillState
	{
		public new Boss parent;

		protected bool flairPlayed;

		protected bool flairEndPlayed;

		protected bool idlePlayed;

		protected float idleNormalizedTime = 0.33f;

		protected float endFlairNormalizedTime = 0.85f;

		protected string idleAnimName;

		public BossReadyState(string newName, FSM newFSM, Boss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			disablePowerUpEffect = true;
			castingAnimName = "Ready";
			idleAnimName = parent.fsm.defaultStateName;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			flairPlayed = false;
			flairEndPlayed = false;
			idlePlayed = false;
			parent.anim.Play(castingAnimName, -1, 0f);
			exitTime = StdExitTime * 2f;
			float num = exitTime * 0.33f;
			exitTime -= num;
			windupStopwatchID = ChaosStopwatch.Begin(num);
		}

		public override void WindupUpdate()
		{
			parent.anim.Play(castingAnimName, -1, 0f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			if (!flairPlayed)
			{
				PlayFlair();
				flairPlayed = true;
			}
		}

		public override void Update()
		{
			base.Update();
			if (!flairEndPlayed && exitQueued)
			{
				float timePercentage = ChaosStopwatch.GetTimePercentage(exitStopwatchID);
				if (!idlePlayed && timePercentage > idleNormalizedTime)
				{
					parent.anim.Play(idleAnimName, -1, 0f);
					idlePlayed = true;
				}
				if (timePercentage >= 0.85f)
				{
					PlayEndFlair();
					flairEndPlayed = true;
				}
			}
		}

		public virtual void PlayFlair()
		{
			parent.anim.Play(castingAnimName, -1, 0.5f);
			CameraController.ShakeCamera();
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 70;
			float scale = 0.5f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		}

		public virtual void PlayEndFlair()
		{
		}

		public override void ExitTransition()
		{
			StartAttackPattern();
		}

		public virtual void StartAttackPattern()
		{
			parent.attackPatternIndex = GetAttackPatternIndex();
			parent.attackIndex = -1;
			parent.TransitionToNextState();
		}

		public virtual int GetAttackPatternIndex()
		{
			if (parent.bossUltimateState != null)
			{
				if (parent.bossUltimateState.UltIsReady)
				{
					return parent.bossUltimateAttackPatternIndex;
				}
				if (!parent.ultUsed && parent.health.HealthPercentage < parent.forceUltHealthPercentage)
				{
					parent.bossUltimateState.UltIsReady = true;
					return parent.bossUltimateAttackPatternIndex;
				}
			}
			return (parent.attackPatternIndex + UnityEngine.Random.Range(1, parent.attackPatternCount)) % parent.attackPatternCount;
		}
	}

	public class BossHurtState : EnemyHurtState
	{
		public string animName = "Hurt";

		public float baseHurtDuration;

		public float maxHurtDuration;

		public float durationIncreaseMultiplier = 1f;

		public int hurtStopwatchID;

		public float stunOverrideValue = 2f;

		public AttackInfo lastAttackInfo;

		public float maxDmgMultiplier = 0.5f;

		public float hitToDmgRatio = 0.02f;

		public int minComboCount = 5;

		public int hitCounter;

		protected bool varsSet;

		private float maxHealthDiff = 0.3f;

		private float recoveryHealthPercentage;

		public new Boss parent;

		public BossHurtState(string newName, FSM newFSM, Boss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			Reset();
		}

		public virtual void SetHurtVars()
		{
			baseHurtDuration = Mathf.Max(0.5f, Mathf.Lerp(0.9f, 0.7f, parent.DifficultyValue) * BaseHurtDurationMultiplier.CurrentValue);
			maxHurtDuration = baseHurtDuration * 2f;
		}

		public override void OnEnter()
		{
			if (!varsSet)
			{
				varsSet = true;
				SetHurtVars();
			}
			if (animName != string.Empty)
			{
				parent.anim.Play(animName, -1, 0f);
			}
			PlayHurtAudio();
			lastAttackInfo = parent.health.lastAttack;
			if (fsm.previousStateName != name)
			{
				HandleDurationIncrease(first: true);
				recoveryHealthPercentage = parent.health.HealthPercentage - maxHealthDiff;
			}
			else if (parent.health.HealthPercentage < recoveryHealthPercentage)
			{
				ChaosStopwatch.Stop(hurtStopwatchID);
				parent.OverdriveBurst(200);
			}
			else
			{
				HandleDurationIncrease();
			}
			HandleStunEffect();
			if (parent.health != null)
			{
				parent.ApplyKnockback(lastAttackInfo);
			}
			if (!Level.isBossRushMode && hitCounter >= minComboCount)
			{
				GameUI.BroadcastNoticeMessage(hitCounter + TextManager.GetUIText("bossRoom-comboCounter"));
			}
		}

		public override void Update()
		{
			exitHurtState = ChaosStopwatch.Check(hurtStopwatchID);
			if (!exitHurtState)
			{
				return;
			}
			if (hitCounter >= minComboCount)
			{
				GameController.stageTitleUI.AnnounceCombo(hitCounter);
				if (bossComboEventHandlers != null)
				{
					bossComboEventHandlers(parent, hitCounter);
				}
			}
			if (hitCounter >= 50)
			{
				AchievementManager.UnlockAchievement(Achievement.HitSpellCombo, forceUnlock: true);
			}
			ExitTransition();
		}

		public override void OnExit()
		{
			if (!parent.fsm.nextStateName.Contains("Hurt"))
			{
				Reset();
			}
		}

		public override void ExitTransition()
		{
			fsm.ChangeState(parent.bossReadyState.name, allowSelfTransition: true);
		}

		public virtual void Reset(bool playStunRecoveryFX = true)
		{
			hitCounter = 0;
			parent.AllowHurtState(status: false);
			if (stunEffect != null)
			{
				stunEffect.Stop(!fsm.nextStateName.Contains("Dead") && fsm.nextStateName.Contains("Fall"));
				stunEffect = null;
			}
		}

		public virtual void HandleDurationIncrease(bool first = false)
		{
			if (first)
			{
				hitCounter = 1;
				hurtStopwatchID = ChaosStopwatch.Begin(baseHurtDuration);
				return;
			}
			if (lastAttackInfo != null && !lastAttackInfo.isStatusEffect)
			{
				hitCounter++;
			}
			hurtStopwatchID = ChaosStopwatch.Begin(Mathf.Min(maxHurtDuration, durationIncreaseMultiplier * baseHurtDuration / (float)hitCounter + ChaosStopwatch.GetRemainingTime(hurtStopwatchID)));
		}

		public virtual void HandleStunEffect()
		{
			if (base.stunEffect == null)
			{
				base.stunEffect = PoolManager.GetPoolItem<StunEffect>();
				base.stunEffect.fullStunOverride = stunOverrideValue;
				base.stunEffect.Play(hurtStopwatchID, parent.transform, Vector3.up * 3.25f);
			}
			else
			{
				StunEffect stunEffect = base.stunEffect;
				int givenStopwatchID = hurtStopwatchID;
				stunEffect.Readjust(-1f, givenStopwatchID);
			}
		}
	}

