	public class BossSkillState : SkillState
	{
		public new Boss parent;

		public override float StdWindupTime => Mathf.Lerp(0.5f, 0.375f, currentDiffValue) * SkillState.WindupMultiStat.CurrentValue;

		public override float StdExitTime => Mathf.Lerp(0.5f, 0.375f, currentDiffValue) * SkillState.ExitMultiStat.CurrentValue;

		public BossSkillState(string newName, FSM newFSM, Boss newEnt)
			: base(newName, newFSM, newEnt, 0, 0, 0f, 0f, 0f, newAuto: false)
		{
			parent = newEnt;
			spellCastColor = Enemy.armorCastColor;
		}

		public override void OnEnter()
		{
			currentDiffValue = parent.DifficultyValue;
			isLegendary = parent.IsLegendary;
			parent.UpdateTargetInfo();
			if (parent.closestTargetInfo != null)
			{
				parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			}

			}
			UpdateTargetVector();
			if (usePowerUpEffect && !disablePowerUpEffect)
			{
				ActivatePowerUpEffect(spellCastColor, Enemy.armorCastColor2, parent.powerUpEffectActive);
				parent.powerUpEffectActive = true;
			}
			windupComplete = false;
			exitQueued = false;
		}

		public override void OnExit()
		{
			if (usePowerUpEffect)
			{
				if (parent.fsm.nextStateName.Contains("Idle") || parent.fsm.nextStateName.Contains("Hurt") || parent.fsm.nextStateName.Contains("Dead"))
				{
					DeactivatePowerUpEffect();
					parent.powerUpEffectActive = false;
				}
				if (powerUpEffect != null)
				{
					powerUpEffect.Deactivate();
				}
			}
		}

		public override void ExitTransition()
		{
			parent.TransitionToNextState();
		}

		public override T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
		{
			return base.ChaosInst<T>(givenPrefab, (!givenPosition.HasValue) ? ((Vector2)parent.transform.position) : givenPosition.Value, (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value, parentTransform ?? parent.bossObjects);
		}

		public override Vector2 UpdateTargetVector(bool updateInfo = false, bool useTransform = false)
		{
			if (updateInfo)
			{
				parent.UpdateTargetInfo();
			}
			if (parent.closestTargetInfo == null || (useTransform && (parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)))
			{
				targetVector = Vector2.zero;
			}
			else
			{
				ref Vector2 reference = ref targetVector;
				Vector3 vector;
				if (useTargetHurtBox)
				{
					vector = ((!useTransform) ? parent.closestTargetInfo.hurtBoxPosition : parent.closestTargetInfo.hurtBoxTransform.position);
				}
				else
				{
					vector = ((!useTransform) ? parent.closestTargetInfo.position : parent.closestTargetInfo.transform.position);
				}
				reference = vector;
				targetVector = ((!useTargetHurtBox) ? (targetVector - (Vector2)parent.transform.position) : (targetVector - (Vector2)parent.attackOriginTrans.position)).normalized;
			}
			return targetVector;
		}
	}

	public class BossDashSkillState : BossSkillState
	{
		public NumVarStatMod dashSpeedMod;

		public NumVarStatMod dashDurationMod;

		public float dashSpeed = 40f;

		public float dashDuration = 0.15f;

		public float dashInterval = 0.5f;

		public float endDashSpeed;

		public int maxDashCount = 1;

		public int dashCounter;

		public bool dashStarted;

		public bool dashCompleted;

		public bool isDashing;

		public bool useRetargetting = true;

		public Vector2 dashVector;

		public bool AllDashesCompleted => dashCounter >= maxDashCount;

		public BossDashSkillState(string newName, FSM newFSM, Boss newEnt)
			: base(newName, newFSM, newEnt)
		{
			dashSpeedMod = new NumVarStatMod(newName, dashSpeed, 10, VarStatModType.OverrideWithMods);
			dashDurationMod = new NumVarStatMod(newName, dashDuration, 10, VarStatModType.OverrideWithMods);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			dashSpeedMod.modValue = dashSpeed;
			parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
			dashDurationMod.modValue = dashDuration;
			parent.movement.dashDurationStat.AddMod(dashDurationMod);
			parent.ToggleFloorContact(allyCollisionOn: false);
			dashCounter = 0;
			ResetReadyVars();
		}

		public override void FixedUpdate()
		{
			if (isDashing && parent.movement.DashToTarget())
			{
				isDashing = false;
				if (endDashSpeed > 0f)
				{
					parent.movement.MoveToMoveVector(endDashSpeed);
				}
			}
		}

		public override void ExecuteSkill()
		{
			if (isDashing)
			{
				return;
			}
			if (!dashStarted)
			{
				if (StartDash())
				{
					dashStarted = true;
					isDashing = true;
				}
			}
			else if (!dashCompleted)
			{
				dashCompleted = EndDash();
			}
			else if (!AllDashesCompleted)
			{
				ResetReadyVars();
			}
			else
			{
				base.ExecuteSkill();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod);
			parent.movement.dashDurationStat.RemoveMod(dashDurationMod);
			parent.ToggleFloorContact();
		}

		public virtual bool StartDash()
		{
			if (useRetargetting)
			{
				UpdateMovementVars();
			}
			parent.FaceTarget(parent.transform.position + (Vector3)targetVector, parent.animFacingDirections);
			dashCounter++;
			return true;
		}

		public virtual bool EndDash()
		{
			windupStopwatchID = ChaosStopwatch.Begin(dashInterval);
			parent.FaceTarget(parent.transform.position + (Vector3)targetVector, parent.animFacingDirections);
			return true;
		}

		public virtual void ResetReadyVars()
		{
			isDashing = false;
			dashStarted = false;
			dashCompleted = false;
		}

		public virtual void UpdateMovementVars()
		{
			parent.movement.moveVector = dashVector;
			parent.movement.dashVector = dashVector;
			parent.movement.dashTimer = dashDuration;
		}
	}

