	public virtual void CreateBossPool<T>(GameObject givenPrefab, int givenCount) where T : class
	{
		bossPoolDict.Add(typeof(T), new GenericPool<T>(givenPrefab, givenCount, bossObjects));
	}

	public virtual GenericPool<T> GetBossPool<T>(Type givenType) where T : class
	{
		return bossPoolDict.GetValue<GenericPool<T>>(givenType);
	}

	public virtual T GetBossPoolItem<T>() where T : class
	{
		return (!(bossObjects == null) && bossPoolDict.ContainsKey(typeof(T))) ? bossPoolDict.GetValue<GenericPool<T>>(typeof(T)).GetItem() : ((T)null);
	}

