public class FireBossIntroState : BossIntroState
{
	public new FireBoss parent;

	private bool bossRevealed;

	private bool idlePausePlayed;

	private bool stretchLeftPlayed;

	private bool stretchRightPlayed;

	private bool squatPlayed;

	private float revealDelay = 0.2f;

	private float idleDelay = 0.75f;

	private ChaosQuickStopwatch revealStopwatch;

	private ChaosQuickStopwatch idleStopwatch;

	public FireBossIntroState(string newName, FSM newFSM, FireBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}

	public override void OnEnter()
	{
		base.OnEnter();
		bossRevealed = false;
		idlePausePlayed = false;
		stretchLeftPlayed = false;
		stretchRightPlayed = false;
		squatPlayed = false;
		parent.anim.Play("Hidden", -1, 0f);
		PlaySpawnEffects(parent.transform.position);
		revealStopwatch = new ChaosQuickStopwatch(revealDelay);
		revealStopwatch.IsRunning = true;
	}

	public override void Update()
	{
		if (!bossRevealed)
		{
			if (!revealStopwatch.IsRunning)
			{
				parent.anim.Play("Idle", -1, 0f);
				idleStopwatch = new ChaosQuickStopwatch(idleDelay);
				idleStopwatch.IsRunning = true;
				bossRevealed = true;
			}
		}
		else
		{
			if (Level.isBossRushMode)
			{
				return;
			}
			if (!idlePausePlayed)
			{
				if (!idleStopwatch.IsRunning)
				{
					parent.anim.Play("StretchLeft", -1, 0f);
					idlePausePlayed = true;
				}
			}
			else if (parent.anim.AnimPlayed())
			{
				if (!stretchRightPlayed)
				{
					stretchRightPlayed = true;
					parent.anim.Play("StretchRight", -1, 0f);
				}
				else if (!stretchLeftPlayed)
				{
					stretchLeftPlayed = true;
					parent.anim.Play("Squat", -1, 0f);
				}
				else if (!squatPlayed)
				{
					squatPlayed = true;
					parent.anim.Play("Idle", -1, 0f);
				}
			}
		}
	}
}

