	public virtual void CleanAllEnemyGroupDicts()
	{
		List<Enemy.EName> list = enemyValuesDict.Keys.ToList();
		for (int num = list.Count - 1; num >= 0; num--)
		{
			Enemy component = Enemy.EnemyPrefabObjects[list[num].ToString()].GetComponent<Enemy>();
			if (component.element != Level.element && component.element != ElementType.Neutral)
			{
				list.RemoveAt(num);
			}
		}
		CleanEnemyGroupDict(list, enemyAddsGroupDict);
		CleanEnemyGroupDict(list, enemyCoreGroupDict);
		CleanEnemyGroupDict(list, enemySurvGroupDict);
	}

	public virtual void CleanEnemyGroupDict(List<Enemy.EName> allowedList, Dictionary<EnemyDecoration, List<EnemyGroup>> givenDict)
	{
		List<Tuple<EnemyDecoration, EnemyGroup>> list = new List<Tuple<EnemyDecoration, EnemyGroup>>();
		foreach (KeyValuePair<EnemyDecoration, List<EnemyGroup>> item in givenDict)
		{
			int count = item.Value.Count;
			for (int i = 0; i < count; i++)
			{
				if (!item.Value[i].IsAllowed(allowedList))
				{
					list.Add(new Tuple<EnemyDecoration, EnemyGroup>(item.Key, item.Value[i]));
				}
			}
		}
		int count2 = list.Count;
		for (int j = 0; j < count2; j++)
		{
			givenDict[list[j].First].Remove(list[j].Second);
		}
		list.Clear();
	}

	public virtual bool PopulateAvailableDecoList(Dictionary<EnemyDecoration, List<EnemyGroup>> givenDict, TileGrid givenTileGrid, bool isAdd = false)
	{
		availableDecorationsList.Clear();
		List<EnemyDecoration> list = givenDict.Keys.ToList();
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			if (givenDict[list[i]].Count != 0 && DecoIsAvailable(list[i], givenTileGrid))
			{
				availableDecorationsList.Add(list[i]);
			}
		}
		if (availableDecorationsList.Count == 0)
		{
			return false;
		}
		wRandomizer.Clear();
		if (!isAdd)
		{
			for (int j = 0; j < availableDecorationsList.Count; j++)
			{
				EnemyDecoration enemyDecoration = availableDecorationsList[j];
				wRandomizer.Add(new WeightedItem<EnemyDecoration>(enemyDecoration, givenDict[enemyDecoration].Count, string.Empty));
			}
		}
		else
		{
			foreach (EnemyGroup item in givenDict[availableDecorationsList[0]])
			{
				wRandomizer.Add(new WeightedItem<EnemyGroup>(item, (int)Mathf.Abs(5f - item.GroupValue), string.Empty));
			}
		}
		return true;
	}

	public virtual bool DecoIsAvailable(EnemyDecoration givenDeco, TileGrid givenTileGrid)
	{
		int rowCount = givenTileGrid.RowCount;
		int colCount = givenTileGrid.ColCount;
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				if (givenDeco.CanPlace(givenTileGrid, i, j))
				{
					return true;
				}
			}
		}
		return false;
	}

