	public virtual void Decorate(TileGrid tileGrid, Room room)
	{
		ClearSpawnPositions();
		currentEnemyPositions.Clear();
		if (initialize)
		{
			InitializeDecorator();
		}
		int x = roomPadding.x;
		int y = roomPadding.y;
		roomEnemyValue = GetRoomValue(tileGrid);
		currentEnemyValue = 0f;
		Dictionary<EnemyDecoration, List<EnemyGroup>> dictionary = null;
		EnemyDecoration enemyDecoration = null;
		EnemyGroup enemyGroup = null;
		EnemyGroup enemyGroup2 = null;
		bool flag = false;
		bool flag2 = true;
		int num = 0;
		bool flag3 = Random.value < 0.35f;
		dictionary = ((!flag3) ? enemyCoreGroupDict : enemySurvGroupDict);
		if (PopulateAvailableDecoList(dictionary, tileGrid))
		{
			enemyDecoration = ((WeightedItem<EnemyDecoration>)wRandomizer.GetRandomItem()).item;
			enemyGroup = new EnemyGroup(dictionary[enemyDecoration].GetRandomValue());
			flag = true;
			currentEnemyValue += enemyGroup.GroupValue * 1f;
			flag2 = enemyGroup.allowAdds;
		}
		if (flag2 && PopulateAvailableDecoList(enemyAddsGroupDict, tileGrid, isAdd: true))
		{
			if (!flag)
			{
				enemyGroup2 = new EnemyGroup(0, addsAllowed: false, Random.value < 0.5f);
			}
			int num2;
			if (flag)
			{
				num2 = ((!flag3) ? ((int)Mathf.Clamp(roomEnemyValue / (currentEnemyValue + 1f), 0f, 2f)) : AddCountRange);
			}
			else
			{
				num2 = 4;
			}
			for (int i = 0; i < num2; i++)
			{
				if (availableDecorationsList.Count == 0)
				{
					break;
				}
				if ((flag || i > 0) && Random.value < 0.2f)
				{
					break;
				}
				EnemyGroup item = ((WeightedItem<EnemyGroup>)wRandomizer.GetRandomItem()).item;
				if (roomEnemyValue - currentEnemyValue - item.GroupValue < 0f)
				{
					break;
				}
				num++;
				if (flag)
				{
					enemyGroup.Add(item.EnemyList, isAdd: true);
				}
				else
				{
					enemyGroup2.Add(item.EnemyList);
				}
				currentEnemyValue += 1f * item.GroupValue;
			}
		}
		if (flag)
		{
			PlaceEnemyGroup(enemyDecoration, enemyGroup, tileGrid, room, spawnAtCenter: true);
		}
		else if (num > 0)
		{
			PlaceEnemyGroup(EnemyAddsDecoration.Adds4x4, enemyGroup2, tileGrid, room, spawnAtCenter: false);
		}
	}

	public virtual float GetRoomValue(TileGrid tileGrid)
	{
		float num = 0f;
		for (int i = 0; i < tileGrid.RowCount; i++)
		{
			for (int j = 0; j < tileGrid.ColCount; j++)
			{
				if (tileGrid[i, j] != null && tileGrid[i, j].terrain == Tile.TerrainType.Floor)
				{
					num++;
				}
			}
		}
		return num * calcSizeValueRatio;
	}

	public virtual bool PlaceEnemyGroup(EnemyDecoration givenDeco, EnemyGroup givenGroup, TileGrid givenTileGrid, Room givenRoom, bool spawnAtCenter)
	{
		IntVec2 validPosition = GetValidPosition(givenTileGrid, givenDeco, spawnAtCenter);
		if (validPosition == IntVec2.zero)
		{
			return false;
		}
		if (givenGroup.isSurvivalRoom)
		{
			Vector2 worldOrigin = givenRoom.GetWorldOrigin(givenTileGrid);
			SpawnSurvivalRoom(worldOrigin, givenTileGrid, givenGroup, givenRoom);
		}
		else
		{
			givenDeco.Place(givenTileGrid, validPosition.x, validPosition.y);
			Vector2 givenLoc = givenRoom.GetWorldOrigin(givenTileGrid) + new Vector2(validPosition.y, -validPosition.x);
			SpawnEnemies(givenLoc, givenDeco, givenGroup, givenRoom.EnemiesTrans);
		}
		return true;
	}

	public virtual List<IntVec2> GetValidPositionList(TileGrid givenTileGrid, EnemyDecoration givenDeco, float excludeRange = -1f)
	{
		validPositions.Clear();
		int rowCount = givenTileGrid.RowCount;
		int colCount = givenTileGrid.ColCount;
		bool flag = excludeRange > 0f;
		Vector2 vector = new Vector2(rowCount, colCount) * 0.5f - Vector2.one * excludeRange;
		Vector2 vector2 = new Vector2(rowCount, colCount) * 0.5f + Vector2.one * excludeRange;
		for (int i = roomPadding.x; i < rowCount - roomPadding.x; i++)
		{
			for (int j = roomPadding.y; j < colCount - roomPadding.y; j++)
			{
				if ((!flag || !((float)i >= vector.x) || !((float)i < vector2.x) || !((float)j >= vector.y) || !((float)j < vector2.y)) && givenDeco.CanPlace(givenTileGrid, i, j))
				{
					validPositions.Add(new IntVec2(i, j));
				}
			}
		}
		return validPositions;
	}

	public virtual IntVec2 GetValidPosition(TileGrid givenTileGrid, EnemyDecoration givenDeco, bool spawnAtCenter = false, float excludeRange = -1f)
	{
		if (spawnAtCenter)
		{
			IntVec2 result = new IntVec2(Mathf.FloorToInt((float)(givenTileGrid.RowCount - givenDeco.RowCount) * 0.5f), Mathf.FloorToInt((float)(givenTileGrid.ColCount - givenDeco.ColCount) * 0.5f));
			if (givenDeco.CanPlace(givenTileGrid, result.x, result.y))
			{
				return result;
			}
		}
		GetValidPositionList(givenTileGrid, givenDeco, excludeRange);
		if (validPositions.Count > 0)
		{
			return validPositions.GetRandomValue();
		}
		availableDecorationsList.Remove(givenDeco);
		return IntVec2.zero;
	}

	public virtual void SpawnEnemies(Vector2 givenLoc, EnemyDecoration givenDeco, EnemyGroup givenEnemyGroup, Transform givenTrans)
	{
		int groupCount = givenEnemyGroup.GroupCount;
		Vector2 zero = Vector2.zero;
		Vector2 vector = new Vector2((givenDeco.ColCount <= 1) ? spawnOffset.x : ((float)Mathf.FloorToInt((float)givenDeco.ColCount * 0.5f)), (givenDeco.RowCount <= 1) ? spawnOffset.y : ((float)(-Mathf.FloorToInt((float)givenDeco.RowCount * 0.5f))));
		int num = Mathf.Clamp(givenEnemyGroup.centerCount, 0, 4);
		bool flag = num > 0;
		for (int i = 0; i < groupCount; i++)
		{
			Vector2 vector2 = Vector2.zero;
			if (num > 0)
			{
				if (flag)
				{
					if (i == num - 1)
					{
						flag = false;
					}
					switch (num)
					{
					case 1:
						zero = Vector2.zero;
						break;
					case 2:
						zero = ((i != 0) ? Vector2.right : Vector2.left);
						zero *= (float)givenDeco.ColCount * 0.25f;
						break;
					default:
						zero = Globals.GetCirclePositionVector(num, i);
						zero = new Vector2(zero.x * (float)givenDeco.ColCount * 0.2f, zero.y * (float)givenDeco.RowCount * 0.2f);
						break;
					}
					vector2 = givenLoc + vector + zero;
				}
				else
				{
					float num2 = 1 - num / 4;
					for (int j = 0; j < 4; j++)
					{
						zero = vector + new Vector2((float)((!(Random.value < 0.5f)) ? 1 : (-1)) * ((float)givenDeco.ColCount * 0.5f - num2), (float)((!(Random.value < 0.5f)) ? 1 : (-1)) * ((float)givenDeco.RowCount * 0.5f - num2));
						if (!currentEnemyPositions.Contains(givenLoc + zero))
						{
							vector2 = givenLoc + zero;
							break;
						}
					}
				}
			}
			else
			{
				for (int k = 0; k < 4; k++)
				{
					zero = vector + new Vector2(Random.Range((float)(-givenDeco.ColCount) * 0.5f + spawnOffset.x, (float)givenDeco.ColCount * 0.5f + spawnOffset.y), Random.Range((float)(-givenDeco.RowCount) * 0.5f + spawnOffset.x, (float)givenDeco.RowCount * 0.5f + spawnOffset.y));
					Vector2 vector3 = givenLoc + zero;
					if (currentEnemyPositions.Contains(vector3))
					{
						continue;
					}
					bool flag2 = false;
					for (int l = 0; l < currentEnemyPositions.Count; l++)
					{
						if (Vector2.Distance(currentEnemyPositions[l], vector3) <= 0.25f)
						{
							flag2 = true;
							break;
						}
					}
					if (!flag2)
					{
						vector2 = vector3;
						break;
					}
				}
			}
			if (vector2 == Vector2.zero)
			{
				continue;
			}
			currentEnemyPositions.Add(vector2);
			Enemy.Spawn(givenEnemyGroup.EnemyList[i], vector2, givenTrans, dropLoot: true, alerted: false, spawnCard: false).name += Globals.generatedPostfix;
			Level.totalEnemyCount++;
			if (Level.doubleEnemies)
			{
				Enemy.Spawn(givenEnemyGroup.EnemyList[i], vector2 + Random.insideUnitCircle * 1.5f, givenTrans, dropLoot: true, alerted: false, spawnCard: false).name += Globals.generatedPostfix;
				Level.totalEnemyCount++;
				if (GameController.coopOn)
				{
					Enemy.Spawn(givenEnemyGroup.EnemyList[i], vector2 + Random.insideUnitCircle * 1.5f, givenTrans, dropLoot: true, alerted: false, spawnCard: false).name += Globals.generatedPostfix;
					Level.totalEnemyCount++;
				}
			}
		}
	}

	public virtual void SpawnSurvivalRoom(Vector2 givenLoc, TileGrid givenTileGrid, EnemyGroup givenEnemyGroup, Room givenRoom)
	{
		int num = givenEnemyGroup.GroupCount - givenEnemyGroup.addsCount;
		int num2 = 4;
		Vector2 vector = new Vector2(givenRoom.tileGrid.ColCount, givenRoom.tileGrid.RowCount);
		float num3 = 1f;
		Vector2 vector2 = new Vector2(givenTileGrid.ColCount, -givenTileGrid.RowCount) * 0.5f;
		int num4;
		if (givenEnemyGroup.centerCount <= 0)
		{
			num4 = ((num - num2 != 1) ? num2 : num);
		}
		else
		{
			num4 = givenEnemyGroup.centerCount;
		}
		SurvivalRoom survivalRoom = null;
		List<EnemyFactory> list = null;
		validPositions = GetValidPositionList(givenTileGrid, EnemySurvivalDecoration.EnemyPlaceDeco, 2f);
		for (int i = 0; i < num; i++)
		{
			if (i % num4 == 0)
			{
				survivalRoom = Object.Instantiate(SurvivalRoom.Prefab, givenLoc + vector2, Quaternion.identity, givenRoom.EnemiesTrans).GetComponent<SurvivalRoom>();
				survivalRoom.order = Mathf.FloorToInt(i / num4);
				survivalRoom.gameObject.name += Globals.generatedPostfix;
				if (i == 0)
				{
					survivalRoom.GetComponent<BoxCollider2D>().size = vector - Vector2.one * 2f;
				}
				else
				{
					Collider2D[] components = survivalRoom.GetComponents<Collider2D>();
					for (int j = 0; j < components.Length; j++)
					{
						components[j].enabled = false;
					}
				}
				list = new List<EnemyFactory>();
			}
			if (validPositions.Count == 0)
			{
				continue;
			}
			IntVec2 randomValue = validPositions.GetRandomValue();
			if (!(randomValue == IntVec2.zero))
			{
				validPositions.Remove(randomValue);
				EnemySurvivalDecoration.EnemyPlaceDeco.Place(givenTileGrid, randomValue.x, randomValue.y);
				EnemyFactory component = Object.Instantiate(EnemyFactory.Prefab, givenLoc + new Vector2(randomValue.y, -randomValue.x) + spawnOffset, Quaternion.identity, survivalRoom.transform).GetComponent<EnemyFactory>();
				component.enemyPrefabKey = givenEnemyGroup.EnemyList[i].ToString();
				component.spawnTimer = (float)(i % num4) * 0.125f + ((i != 0) ? 0f : num3);
				component.invalidSpawnArea = Vector2.zero;
				component.enemiesPerCycle = 1;
				if (Level.doubleEnemies)
				{
					component.spawnArea = Vector2.one * 1.5f;
					component.spawnInterval = 0.25f;
					component.maxSpawnCycles = ((!GameController.coopOn) ? 2 : 3);
				}
				else
				{
					component.spawnArea = Vector2.zero;
					component.maxSpawnCycles = 1;
				}
				list.Add(component);
				Level.totalEnemyCount += component.maxSpawnCycles * component.enemiesPerCycle;
			}
		}
		if (survivalRoom != null && Random.value < 0.25f)
		{
			survivalRoom.spawnTreasureChest = true;
			survivalRoom.treasureChestLootID = "TreasureChestSmall";
		}
		if (givenEnemyGroup.addsCount > 0)
		{
			int num5 = givenEnemyGroup.GroupCount - givenEnemyGroup.addsCount;
			EnemyGroup enemyGroup = new EnemyGroup(givenEnemyGroup.addsCount, addsAllowed: false);
			for (int k = num5; k < givenEnemyGroup.GroupCount; k++)
			{
				enemyGroup.Add(givenEnemyGroup.EnemyList[k]);
			}
			PlaceEnemyGroup(EnemyAddsDecoration.Adds4x4, enemyGroup, givenTileGrid, givenRoom, spawnAtCenter: true);
		}
	}
}

using System.Collections.Generic;
using UnityEngine;

public class EnemyFactory : MonoBehaviour
{
	private static GameObject prefab;

	public string enemyPrefabKey;

	public bool enemiesDropLoot = true;

	public bool disableCountDeath;

	public bool spawning;

	public bool autoAlertEnemies;

	public bool wasActivated;

	private bool wasSpawning;

	public float spawnInterval;

	public bool randomSpawnTimer;

	public float spawnTimer;

	private int spawnStopwatchID = -1;

	public int maxSpawnCycles;

	public int currentSpawnCycle;

	public int enemiesPerCycle;

	public Vector2 spawnOrigin;

	public Vector2 spawnArea;

	public Vector2 invalidSpawnOrigin;

	public Vector2 invalidSpawnArea;

	private Vector3 spawnOriginWorld;

	private Vector3 halfArea;

	private Vector3 botLeft;

	private Vector3 topRight;

	private Vector3 botRight;

	private Vector3 topLeft;

	private Vector3 invalidSpawnOriginWorld;

	private Vector3 invalidHalfArea;

	private Vector3 invalidBotLeft;

	private Vector3 invalidTopRight;

	private Vector3 invalidBotRight;

	private Vector3 invalidTopLeft;

	[HideInInspector]
	public Transform enemyLocations;

	public List<Enemy> spawnedEnemies;

	private GameObject enemyPrefab;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/EnemyFactory.prefab"));

	private void Awake()
	{
		InitEnemyContainer();
		spawnedEnemies = new List<Enemy>();
		wasActivated = spawning;
	}

	private void Start()
	{
		enemyPrefab = ChaosBundle.Get(Enemy.enemyPrefabPaths[enemyPrefabKey]);
		SetSpawnAreaExtents();
	}

	private void Update()
	{
		if (!spawning)
		{
			wasSpawning = false;
			return;
		}
		if (!wasSpawning)
		{
			wasSpawning = true;
			spawnStopwatchID = ChaosStopwatch.Begin((!randomSpawnTimer) ? spawnTimer : Random.Range(1f, spawnTimer));
		}
		if (maxSpawnCycles >= 0 && currentSpawnCycle >= maxSpawnCycles)
		{
			spawning = false;
		}
		else if (ChaosStopwatch.Check(spawnStopwatchID))
		{
			wasActivated = true;
			for (int i = 0; i < enemiesPerCycle; i++)
			{
				Enemy enemy = Enemy.Spawn(enemyPrefabKey, GetRandomLocation(), enemyLocations, enemiesDropLoot, alerted: false, spawnCard: true, autoAlertEnemies, disableCountDeath);
				spawnedEnemies.Add(enemy);
				enemy.parentFactoryList = spawnedEnemies;
			}
			spawnStopwatchID = ChaosStopwatch.Begin((!randomSpawnTimer) ? spawnInterval : Random.Range(1f, spawnInterval));
			currentSpawnCycle++;
		}
	}

	public bool AllEnemiesCleared()
	{
		if (!wasActivated || spawning)
		{
			return false;
		}
		foreach (Enemy spawnedEnemy in spawnedEnemies)
		{
			if (spawnedEnemy != null && (spawnedEnemy.health.healthStat.CurrentValue > 0f || !spawnedEnemy.fsm.currentStateName.Contains("Dead")))
			{
				return false;
			}
		}
		return true;
	}

	private void InitEnemyContainer()
	{
		Transform transform = base.transform.root.Find("EnemyLocations");
		if (transform == null)
		{
			transform = base.transform.root.Find("Enemies");
		}
		if (transform == null && base.transform.parent != null)
		{
			transform = base.transform.parent.Find("Enemies");
		}
		if (transform == null)
		{
			transform = new GameObject("Enemies").transform;
			transform.SetParent(base.transform.parent);
		}
		enemyLocations = transform;
	}

	private void SetSpawnAreaExtents()
	{
		spawnOriginWorld = transform.TransformPoint(spawnOrigin);
		halfArea = spawnArea * 0.5f;
		botLeft = spawnOriginWorld - halfArea;
		topRight = spawnOriginWorld + halfArea;
		botRight = new Vector2(spawnOriginWorld.x + halfArea.x, spawnOriginWorld.y - halfArea.y);
		topLeft = new Vector2(spawnOriginWorld.x - halfArea.x, spawnOriginWorld.y + halfArea.y);
		invalidSpawnOriginWorld = transform.TransformPoint(invalidSpawnOrigin);
		invalidHalfArea = invalidSpawnArea * 0.5f;
		invalidBotLeft = invalidSpawnOriginWorld - invalidHalfArea;
		invalidTopRight = invalidSpawnOriginWorld + invalidHalfArea;
		invalidBotRight = new Vector2(invalidSpawnOriginWorld.x + invalidHalfArea.x, invalidSpawnOriginWorld.y - invalidHalfArea.y);
		invalidTopLeft = new Vector2(invalidSpawnOriginWorld.x - invalidHalfArea.x, invalidSpawnOriginWorld.y + invalidHalfArea.y);
	}

	private Vector3 GetRandomLocation()
	{
		if (spawnArea == Vector2.zero)
		{
			return spawnOriginWorld;
		}
		int num = 0;
		if (invalidSpawnArea != Vector2.zero)
		{
			num = Random.Range(1, 5);
		}
		return num switch
		{
			1 => new Vector3(Random.Range(botLeft.x, invalidBotLeft.x), Random.Range(botLeft.y, topLeft.y)), 
			2 => new Vector3(Random.Range(invalidBotRight.x, botRight.x), Random.Range(botLeft.y, topLeft.y)), 
			3 => new Vector3(Random.Range(invalidBotLeft.x, invalidBotRight.x), Random.Range(invalidTopLeft.y, topLeft.y)), 
			4 => new Vector3(Random.Range(invalidBotLeft.x, invalidBotRight.x), Random.Range(botLeft.y, invalidBotLeft.y)), 
			_ => new Vector3(Random.Range(botLeft.x, botRight.x), Random.Range(botLeft.y, topLeft.y)), 
		};
	}

	private void OnDrawGizmosSelected()
	{
		SetSpawnAreaExtents();
		Gizmos.color = Color.green;
		Gizmos.DrawLine(botLeft, topLeft);
		Gizmos.DrawLine(topLeft, topRight);
		Gizmos.DrawLine(topRight, botRight);
		Gizmos.DrawLine(botLeft, botRight);
		Gizmos.color = Color.red;
		Gizmos.DrawLine(invalidBotLeft, invalidTopRight);
		Gizmos.DrawLine(invalidTopLeft, invalidBotRight);
		Gizmos.DrawLine(invalidBotLeft, invalidTopLeft);
		Gizmos.DrawLine(invalidTopLeft, invalidTopRight);
		Gizmos.DrawLine(invalidTopRight, invalidBotRight);
		Gizmos.DrawLine(invalidBotLeft, invalidBotRight);
		if (invalidSpawnArea.x > spawnArea.x - 2f)
		{
			invalidSpawnArea.x = spawnArea.x - 2f;
			invalidSpawnOrigin.x = spawnOrigin.x;
		}
		if (invalidSpawnArea.y > spawnArea.y - 2f)
		{
			invalidSpawnArea.y = spawnArea.y - 2f;
			invalidSpawnOrigin.y = spawnOrigin.y;
		}
		if (invalidTopLeft.x < botLeft.x + 1f)
		{
			invalidSpawnOrigin.x += botLeft.x + 1f - invalidTopLeft.x;
		}
		if (invalidTopRight.x > topRight.x - 1f)
		{
			invalidSpawnOrigin.x += topRight.x - 1f - invalidTopRight.x;
		}
		if (invalidBotLeft.y < botLeft.y + 1f)
		{
			invalidSpawnOrigin.y += botLeft.y + 1f - invalidBotLeft.y;
		}
		if (invalidTopRight.y > topRight.y - 1f)
		{
			invalidSpawnOrigin.y += topRight.y - 1f - invalidTopRight.y;
		}
		if (invalidSpawnArea.x < 0f || invalidSpawnArea.y < 0f)
		{
			invalidSpawnArea = Vector2.zero;
		}
	}

	public void ResetFactory()
	{
		spawning = false;
		wasSpawning = false;
		wasActivated = false;
		currentSpawnCycle = 0;
		spawnStopwatchID = -1;
		foreach (Enemy spawnedEnemy in spawnedEnemies)
		{
			if (!(spawnedEnemy == null) && !(spawnedEnemy.gameObject == null) && !(spawnedEnemy.fsm.currentStateName == "Dead"))
			{
				spawnedEnemy.dropLoot = false;
				spawnedEnemy.dropLootChest = false;
				if (spawnedEnemy.fsm.HasState("Dead"))
				{
					spawnedEnemy.fsm.QueueChangeState("Dead");
					continue;
				}
				Object.Destroy(spawnedEnemy.gameObject);
				Enemy.SpawnEnemyPortal(spawnedEnemy.transform.position);
			}
		}
		spawnedEnemies.Clear();
	}
}
