public void Activate(GameObject[] gates = null, RetractableWall[] wallScripts = null)
{
	if (triggered)
	{
		return;
	}
	triggered = true;
	EnemyFactory[] array = enemyFactories;
	foreach (EnemyFactory enemyFactory in array)
	{
		for (int j = 0; j < enemyFactory.spawnedEnemies.Count; j++)
		{
			Enemy enemy = enemyFactory.spawnedEnemies[j];
			if (roomScript.name != Level.tileGrid[enemy.lastTileRow, enemy.lastTileCol].roomStub.name)
			{
				enemyFactory.spawnedEnemies.RemoveAt(j);
				j--;
			}
		}
		enemyFactory.spawning = true;
	}
	if (gates != null && wallScripts != null)
	{
		northGate = gates[0];
		southGate = gates[1];
		eastGate = gates[2];
		westGate = gates[3];
		retractableWalls = wallScripts;
	}
	else if (roomScript != null)
	{
		InstantiateWalls();
		ToggleGates();
		RetractableWall[] array2 = retractableWalls;
		foreach (RetractableWall retractableWall in array2)
		{
			if ((retractableWall.wallType & roomScript.AllowedConnections) == retractableWall.wallType || retractableWall.wallType == MapDirections.Everything || retractableWall.wallType == MapDirections.None)
			{
				retractableWall.Activate();
			}
		}
	}
	if (hazardRoom != null)
	{
		hazardRoom.HazardTriggered(overrideShutdown: true);
		if (hazardRoomList == null)
		{
			hazardRoomList = new List<HazardRoom>();
		}
		hazardRoomList.Add(hazardRoom);
	}
	if (order > 0)
	{
		return;
	}
	Player[] activePlayers = GameController.activePlayers;
	foreach (Player player in activePlayers)
	{
		if (checkpointTrans != null)
		{
			player.lastCheckpoint = checkpointTrans.position;
			player.fall.preFallPos = checkpointTrans.position;
		}
		if (player.playerID != targetPlayerID)
		{
			player.RequestTeleportMoveToLocation(targetPlayer.transform.position, useCheck: true);
		}
	}
	Player.OnSurvivalRoomEnter((!(checkpointTrans == null)) ? checkpointTrans.position : Vector3.zero);
	SoundManager.PlayAudio("RoomLock");
}

public void Disable(bool roomStatus = true, bool skipGateLogic = false)
{
	roomCleared = roomStatus;
	if (!skipGateLogic)
	{
		RetractableWall[] array = retractableWalls;
		foreach (RetractableWall retractableWall in array)
		{
			retractableWall.Disable();
		}
		ToggleGates(enable: false);
		if (roomCleared)
		{
			StartCoroutine(PlayWinFX());
			if (onSurvivalRoomClearEventHandlers != null)
			{
				onSurvivalRoomClearEventHandlers();
			}
		}
		else
		{
			SoundManager.PlayAudio("Rumble");
		}
		foreach (HazardRoom hazardRoom in hazardRoomList)
		{
			if (hazardRoom != null)
			{
				hazardRoom.ForceShutdown();
			}
		}
	}
	if (spawnTreasureChest && roomCleared && GameController.GetAlivePlayerCount() > 0)
	{
		TreasureChest treasureChest = Globals.ChaosInst<TreasureChest>(TreasureChest.Prefab, transform.parent, transform.position);
		treasureChest.lootTableName = treasureChestLootID;
		treasureChest.preventElemental = true;
	}
}

