	public void Update()
	{
		if (!triggered || roomCleared)
		{
			return;
		}
		if (ChaosStopwatch.Check(intervalStopwatchID))
		{
			intervalStopwatchID = ChaosStopwatch.Begin(checkPlayerStatusInterval);
			if (!CheckPlayers())
			{
				ResetSurvivalRooms();
			}
		}
		if (CheckSpawners())
		{
			bool skipGateLogic = order != survivalRooms.Length - 1;
			Disable(roomStatus: true, skipGateLogic);
			EnableNextRooms();
		}
	}

	public void EnableNextRooms()
	{
		for (int i = 0; i < survivalRooms.Length; i++)
		{
			if (survivalRooms[i].order == order + 1)
			{
				survivalRooms[i].hazardRoomList = hazardRoomList;
				survivalRooms[i].Activate(new GameObject[4] { northGate, southGate, eastGate, westGate }, retractableWalls);
			}
		}
	}

	public bool CheckPlayers()
	{
		Player[] playerScripts = GameController.playerScripts;
		foreach (Player player in playerScripts)
		{
			if (player != null && player.currentStateName != "Dead")
			{
				return true;
			}
		}
		return false;
	}

	private void ResetSurvivalRooms()
	{
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			survivalRoom.Disable(roomStatus: false, survivalRoom != this);
			survivalRoom.triggered = false;
			EnemyFactory[] array2 = survivalRoom.enemyFactories;
			foreach (EnemyFactory enemyFactory in array2)
			{
				enemyFactory.ResetFactory();
			}
		}
	}

	public bool CheckSpawners()
	{
		EnemyFactory[] array = enemyFactories;
		foreach (EnemyFactory enemyFactory in array)
		{
			if (!enemyFactory.AllEnemiesCleared())
			{
				return false;
			}
		}
		return true;
	}
}

	public static Enemy Spawn(EName enumName, Vector3 enemyPosition, Transform parentTrans = null, bool dropLoot = true, bool alerted = false, bool spawnCard = true, bool survivalMode = false, bool overrideCountDeath = false)
	{
		return Spawn(enumName.ToString(), enemyPosition, parentTrans, dropLoot, alerted, spawnCard, survivalMode, overrideCountDeath);
	}

	public static Enemy Spawn(string enemyName, Vector3 enemyPosition, Transform parentTrans = null, bool dropLoot = true, bool alerted = false, bool spawnCard = true, bool survivalMode = false, bool overrideCountDeath = false)
	{
		if (EnemyDecorator.useRandomElementalEnemies && !neutralEnemyIDs.Contains(enemyName) && baseEnemyName.ContainsKey(enemyName))
		{
			enemyName = GetRandomElementalEnemyPrefab(baseEnemyName[enemyName]);
		}
		GameObject gameObject = UnityEngine.Object.Instantiate(EnemyPrefabObjects[enemyName], Vector3.zero, Quaternion.identity);
		gameObject.transform.SetParent(parentTrans);
		gameObject.transform.position = enemyPosition;
		Enemy enemy = gameObject.GetComponent<Enemy>();
		if (enemy == null)
		{
			enemy = gameObject.GetComponentsInChildren<Enemy>()[0];
