	public override TargetInfo UpdateTargetInfo(float rangeOverride = -1f, bool reqLOS = false)
	{
		if (!fsm.currentStateName.Contains("FinalBossChaos") && fsm.currentStateName != "FireBossDragonLine" && fsm.currentStateName != "EarthBossRockThrow")
		{
			closestTargetInfo = Entity.GetClosestTarget(targetGroup, transform.position, (!(rangeOverride > 0f)) ? CurrentAlertRadius : rangeOverride, onlyTargetPlayers, null, gameObject, reqLOS, reqLOS ? lineOfSightLayerMask : 0);
			return closestTargetInfo;
		}
		return base.UpdateTargetInfo(rangeOverride, reqLOS);
	}

	public override void TransitionToNextState()
	{
		if (chaosMode)
		{
			if (fsm.currentStateName == chaosShieldState.name || fsm.currentStateName == idleShieldState.name)
			{
				chaosIndex = (chaosIndex + UnityEngine.Random.Range(1, chaosCount)) % chaosCount;
				fsm.ChangeState(chaosPatternList[chaosIndex].name, allowSelfTransition: true);
			}
			else
			{
				fsm.ChangeState(idleShieldState.name);
			}
			return;
		}
		if (UpdateTargetInfo() == null)
		{
			fsm.ChangeState(fsm.defaultStateName);
			return;
		}
		nextAttackIndex = attackIndex + 1;
		if (nextAttackIndex < 0 || nextAttackIndex >= attackIndexCurrentMax)
		{
			if (superMode)
			{
				bossUltimateState = superEraserState;
				if (!bossUltimateState.UltIsReady)
				{
					chaosFinisherUsed = true;
				}
			}
			if (chaosFinisherUsed)
			{
				chaosFinisherUsed = false;
				standardPatternList.Shuffle();
				superPatternList.Shuffle();
				AllowHurtState(status: true);
				nextSkillRange = -1f;
				if (bossTargetList != null && bossTargetList.Count == 0)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
				else
				{
					fsm.ChangeState(bossDashState.name, allowSelfTransition: true);
				}
			}
			else
			{
				chaosFinisherUsed = true;
				if (!superMode)
				{
					chaosIndex = (chaosIndex + UnityEngine.Random.Range(1, chaosCount)) % chaosCount;
					bossUltimateState = chaosPatternList[chaosIndex];
				}
				bossUltimateState.queueUltimate = true;
				fsm.ChangeState(bossUltimateState.name, allowSelfTransition: true);
			}
			return;
		}
		AllowHurtState(status: false);
		if (superMode)
		{
			nextAttackName = superPatternList[nextAttackIndex].name;
		}
		else
		{
			nextAttackName = standardPatternList[nextAttackIndex].name;
			if (nextAttackIndex == attackIndexCurrentMax - 1)
			{
				nextAttackName = bossSkillDict[nextAttackName];
			}
		}
		nextSkillRange = ((!skillRangeDict.ContainsKey(nextAttackName)) ? 8f : skillRangeDict[nextAttackName]);
		if (fsm.currentStateName != bossDashState.name)
		{
			fsm.ChangeState(bossDashState.name, allowSelfTransition: true);
			return;
		}
		attackIndex++;
		fsm.ChangeState(nextAttackName, allowSelfTransition: true);
		if (!superMode)
		{
			EmitElement(skillEleDict[nextAttackName]);
		}
	}

	public override void AllowHurtState(bool status)
	{
		base.AllowHurtState(status);
		evadeMode = status;
		if (status)
		{
			if (superMode)
			{
				evadeStopwatch.SetDelay(Mathf.Max(0.25f, Mathf.Lerp(0.5f, 1f, health.HealthPercentage) * SkillState.CooldownMultiStat.CurrentValue), stopCurrent: true, autoStart: true);
			}
			else
			{
				evadeStopwatch.SetDelay(Mathf.Max(0.25f, Mathf.Lerp(1.4f, 2f, health.HealthPercentage) * SkillState.CooldownMultiStat.CurrentValue), stopCurrent: true, autoStart: true);
			}
		}
		else
		{
			evadeStopwatch.IsRunning = false;
		}
		if (status && !chaosMode && !fsm.currentStateName.Contains("Dead"))
		{
			PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, transform.position);
			SetOutlineColor(Color.clear, Color.clear);
		}
	}

	protected Vector2 GetTrackingVector(float trackVal = 3f)
	{
		UpdateTargetInfo();
		if (closestTargetInfo == null || closestTargetInfo.hurtBoxTransform == null || closestTargetInfo.entity == null)
		{
			return Vector2.zero;
		}
		return (closestTargetInfo.hurtBoxPosition + (Vector3)closestTargetInfo.entity.rigidbody2D.velocity.normalized * Mathf.Min(trackVal, Mathf.Abs(closestTargetInfo.distance - 1f) / Mathf.Max(trackVal, 1f)) - attackOriginTrans.position).normalized;
	}

	public void ToggleShieldHurtBox(bool enable = true)
	{
		if (enable)
		{
			normalHurtBoxCollider.enabled = false;
			shieldHurtBoxCollider.enabled = true;
			hurtBoxCollider = shieldHurtBoxCollider;
			normalFloorContactCollider.enabled = false;
			shieldFloorContactCollider.enabled = true;
		}
		else
		{
			normalHurtBoxCollider.enabled = true;
			shieldHurtBoxCollider.enabled = false;
			hurtBoxCollider = normalHurtBoxCollider;
			normalFloorContactCollider.enabled = true;
			shieldFloorContactCollider.enabled = false;
		}
	}

	private void InitAttackPatterns()
	{
		standardPatternList = new List<BossSkillState> { fireAtkState, airAtkState, earthAtkState, lightningAtkState, waterAtkState };
		standardPatternList.Shuffle();
		chaosPatternList = new List<BossUltimateState> { chaosGrabState, chaosBallState, chaosWaveState, chaosBeamState, chaosSummonState };
		chaosCount = chaosPatternList.Count;
		chaosIndex = UnityEngine.Random.Range(0, chaosCount);
		superPatternList = new List<BossSkillState> { superScytheState, superLungeState, superCoilState, superBeamState, superSpearState, superClusterState };
	}

	private void EmitElement(ElementType givenElement)
	{
		StartCoroutine(EmitElementParticles(givenElement));
	}

	private IEnumerator EmitElementParticles(ElementType givenElement)
	{
		elementEmitter.startColor = eleColorDict[givenElement];
		elementEmitter.Emit(50);
		elementEmitter.Play();
		yield return waitForEmitDelay;
		elementEmitter.Stop();
	}
}

