public class FinalBossDashState : BossSkillState
{
	private Vector2 diffVector;
	private float vectorWeight;
	private bool dashComplete;
	private ChaosQuickStopwatch lockStopwatch = new ChaosQuickStopwatch(1.75f);
	private int delayStopwatchID;
	private float chaseDelay = 0.0625f;
	private float evadeDelay = 0.75f;
	private BoolVarStatMod airborneStatMod;
	private Vector2 currentPosition;
	private Vector2 effectPosition;
	private ChaosQuickStopwatch teleportStopwatch = new ChaosQuickStopwatch(0.125f);
	private float teleLerpValue;
	private Vector2 startPosition;
	private Vector2 endPosition;
	private bool finishedDashing;
	public new FinalBoss parent;
	public bool UseDash => parent.closestTargetInfo != null && Vector2.Distance(parent.transform.position, parent.closestTargetInfo.position) > parent.nextSkillRange;
	public FinalBossDashState(string newName, FSM newFSM, FinalBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		playPowerUpAudio = false;
		useTargetHurtBox = false;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 5);
	}
	public override void OnEnter()
	{
		disablePowerUpEffect = parent.superMode;
		if (!UseDash)
		{
			ExitTransition();
			return;
		}
		usePowerUpEffect = !parent.evadeMode;
		base.OnEnter();
		currentPosition = parent.transform.position;
		if (parent.evadeMode)
		{
			Vector2 stageCenter = parent.stageCenter;
			float radius = ((!parent.superMode) ? 7f : 9f);
			targetVector = (stageCenter.Randomize(1f, radius) - currentPosition).normalized;
			if (parent.superMode)
			{
				parent.health.invulnerable = false;
			}
		}
		else
		{
			if (fsm.previousStateName != name)
			{
				lockStopwatch.SetDelay(parent.SpellStartTime * 3.5f, stopCurrent: true, autoStart: true);
			}
			vectorWeight = UnityEngine.Random.Range(lockStopwatch.TimePercentage, 1f);
			targetVector = (targetVector * vectorWeight + Globals.GetPerpendicular(targetVector, Globals.RandBool) * (1f - vectorWeight)).normalized;
		}
		if (parent.superMode)
		{
			startPosition = currentPosition;
			endPosition = startPosition + targetVector * 6f;
			parent.movement.moveVector = targetVector;
			SpawnTeleportEffect();
			string audioID = "ChaosBeamStart";
			Vector2? soundOrigin = currentPosition;
			teleportStopwatch.IsRunning = true;
			ToggleColliders(givenStatus: false);
			finishedDashing = false;
		}
		else
		{
			parent.movement.dashVector = targetVector;
			PlayDashEffects(targetVector);
			SetDashVars(givenStatus: true);
		}
		parent.FaceTarget(currentPosition + targetVector, parent.animFacingDirections);
	}
	public override void Update()
	{
		if (ChaosStopwatch.Check(delayStopwatchID) && (!parent.superMode || finishedDashing) && dashComplete)
		{
			if (parent.evadeMode && !parent.evadeStopwatch.IsRunning)
			{
				fsm.ChangeState(parent.bossReadyState.name, allowSelfTransition: true);
			}
			else if (UseDash)
			{
				fsm.ChangeState(name, allowSelfTransition: true);
			}
			else
			{
				ExitTransition();
			}
		}
	}
	public override void FixedUpdate()
	{
		if (parent.superMode)
		{
			if (finishedDashing)
			{
				return;
			}
			teleLerpValue = teleportStopwatch.TimePercentage;
			if (teleLerpValue >= 1f)
			{
				finishedDashing = true;
				dashComplete = true;
				parent.rigidbody2D.MovePosition(endPosition);
				parent.movement.MoveToMoveVector(12f);
				if (parent.evadeMode)
				{
					delayStopwatchID = ChaosStopwatch.Begin(Mathf.Max(0.125f, evadeDelay * UnityEngine.Random.Range(0.625f, 0.75f) * SkillState.CooldownMultiStat.CurrentValue));
				}
				else
				{
					delayStopwatchID = ChaosStopwatch.Begin(0.04f);
				}
				SpawnTeleportEffect(givenStart: false);
				string audioID = "EnemyDead";
				Vector2? soundOrigin = parent.transform.position;
				float overridePitch = UnityEngine.Random.Range(1.1f, 1.2f);
				ToggleColliders(givenStatus: true);
			}
			else
			{
				parent.rigidbody2D.MovePosition(Vector2.Lerp(startPosition, endPosition, teleLerpValue));
			}
		}
		else if (!dashComplete && parent.movement.DashToTarget(null, snap: false, ignoreDashTimer: false, endMovementOnFinish: false))
		{
			dashComplete = true;
			if (parent.evadeMode)
			{
				delayStopwatchID = ChaosStopwatch.Begin(Mathf.Max(0.125f, evadeDelay * UnityEngine.Random.Range(1f, 1.5f) * SkillState.CooldownMultiStat.CurrentValue));
			}
			else
			{
				delayStopwatchID = ChaosStopwatch.Begin(chaseDelay);
			}
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		if (parent.superMode)
		{
			ToggleColliders(givenStatus: true);
		}
		else
		{
			SetDashVars(givenStatus: false);
