		{
			parent.movement.moveVector = targetVector;
			parent.movement.MoveToMoveVector(20f);
			comboCount++;
			finalHit = comboCount >= maxComboCount;
			animName = ((!(animName == "Forehand")) ? "Forehand" : "Backhand");
			CreateWindSlash();
			if (finalHit)
			{
				base.ExecuteSkill();
			}
			else
