		private void CreateWindSlash()
		{
			if (currentWS != null)
			{
				currentWS.transform.SetParent(parent.bossObjects);
			}
			currentWS = ChaosInst<MeleeAttackObject>(windSlashPrefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(targetVector), parent.attackOriginTrans);
			currentWS.attack.SetAttackInfo(parent.skillCategory, skillID, comboCount);
			currentWS.attack.knockbackOverwriteVector = targetVector;
			currentWS.transform.localScale = Vector3.one * attackScale;
			currentProj = ChaosInst<Projectile>(projectilePrefab, currentWS.transform.position, Globals.GetRotationQuaternion(targetVector));
			currentProj.parentObject = parent.gameObject;
			currentProj.parentEntity = parent;
			currentProj.moveVector = targetVector;
			currentProj.attackBox.SetAttackInfo(parent.skillCategory, skillID, comboCount + 1);
			currentProj.flyTime = 0.125f;
			currentProj.alwaysWinCollision = true;
		}
	}
